    /**
     * @method
     * @name bit2me#fetchMarkets
     * @description retrieves data on all markets for bit2me
     * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v2/trading/market-config/get
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.marketEnabled] filter by market state, one of 'enabled', 'enabled_at', 'frozen', 'restricted'
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> response = await this.publicGetV2TradingMarketConfig(parameters);
        //
        //     [
        //         {
        //             "id": "5daf7851-c883-4e34-ad1a-52a8bb7651e3",
        //             "symbol": "BTC/EUR",
        //             "marketEnabled": "enabled",
        //             "marketEnabledAt": null,
        //             "minAmount": 0.00006,
        //             "maxAmount": 20,
        //             "minPrice": 7500,
        //             "maxPrice": 7500000,
        //             "minOrderSize": 1,
        //             "tickSize": 0.1,
        //             "initialPrice": 0,
        //             "pricePrecision": 1,
        //             "amountPrecision": 8,
        //             "feeMakerPercentage": 0,
        //             "feeTakerPercentage": 0
        //         }
        //     ]
        //
        return ccxt.BaseExchange.ToMarketInterfaceList(this.parseMarkets(response));
    }

    public override Dictionary<string, object> parseMarket(object market)
    {
        string? id = this.safeString(market, "symbol", "");
        List<object> parts = id.Split(new [] {"/"}, StringSplitOptions.None).ToList<object>();
        string? baseId = this.safeString(parts, 0);
        string? quoteId = this.safeString(parts, 1);
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        string? status = this.safeString(market, "marketEnabled");
        IDictionary<string, object> fees = this.fees;
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", id },
            { "symbol", (bs == null ? null : bs + "/" + quote) },
            { "base", bs },
            { "quote", quote },
            { "settle", null },
            { "baseId", baseId },
            { "quoteId", quoteId },
            { "settleId", null },
            { "type", "spot" },
            { "spot", true },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "active", (status == "enabled") },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", null },
            { "expiryDatetime", null },
            { "strike", null },
            { "optionType", null },
            { "taker", getValue((fees != null && fees.ContainsKey("trading") ? fees["trading"] : null), "taker") },
            { "maker", getValue((fees != null && fees.ContainsKey("trading") ? fees["trading"] : null), "maker") },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "amountPrecision"))) },
                { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "pricePrecision"))) },
                { "cost", null },
            } },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minAmount") },
                    { "max", this.safeNumber(market, "maxAmount") },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minPrice") },
                    { "max", this.safeNumber(market, "maxPrice") },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minOrderSize") },
                    { "max", null },
                } },
            } },
            { "created", this.parse8601(this.safeString(market, "marketEnabledAt")) },
            { "info", market },
        });
    }

    /**
     * @method
     * @name bit2me#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://api.bit2me.com/docs/wallet/rest-overview
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.includeTestnet] default false, when true testnet assets are included
     * @returns {object} an associative dictionary of currencies
     */
    public async override Task<IDictionary<string, object>> fetchCurrencies(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        (bool?, IDictionary<string, object>) includeTestnetqueryVariable = this.handleOptionBoolAndParams(parameters, "fetchCurrencies", "includeTestnet", false);
        bool? includeTestnet = includeTestnetqueryVariable.Item1;
        IDictionary<string, object> query = (includeTestnetqueryVariable.Item2);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "includeTestnet", (includeTestnet == true) ? "true" : "false" },
        };
        List<object> promises = new List<object> {this.publicGetV2CurrencyAssets(this.extend(request, query)), this.publicGetV1WalletSettingsAssets(query)};
        List<object> responses = await promiseAll(promises);
        //
        // assets
        //
        //     {
        //         "BTC": {
        //             "symbol": "BTC",
        //             "name": "Bitcoin",
        //             "slug": "bitcoin",
        //             "mainwebUri": "bitcoin",
        //             "uriScheme": "bitcoin",
        //             "hexColor": "#eca24d",
        //             "assetType": "currency",
        //             "addressRegex": "^([13][a-km-zA-HJ-NP-Z1-9]{25,34})|...",
        //             "hasImage": true,
        //             "hasPaymentRequest": true,
        //             "isERC20Token": false,
        //             "image": "/crypto-icons/v8/svg/btc-circle-solid-default.svg",
        //             "network": "BITCOIN",
        //             "enabled": true,
        //             "lite": false,
        //             "pairsWith": [ "EUR" ],
        //             "ticker": true,
        //             "loanable": true,
        //             "exponent": 8, // optional
        //             "createdAt": "2024-10-08", // optional
        //             "removedAt": "2025-05-22T00:00:00.000Z" // optional, set for delisted assets
        //         }
        //     }
        //
        // wallet settings
        //
        //     [
        //         {
        //             "symbol": "BTC",
        //             "actions": [ "deposit", "deposit-app", "deposit-web", "earn", "instant", "purchase", "transfer", "withdrawal" ]
        //         }
        //     ]
        //
        IDictionary<string, object> assets = this.safeDict(responses, 0, new Dictionary<string, object>() {});
        List<object> settings = this.safeList(responses, 1, new List<object>() {});
        Dictionary<string, object> settingsById = this.indexBy(settings, "symbol");
        List<object> ids = new List<object>(assets.Keys);
        Dictionary<string, object> result = new Dictionary<string, object>() {};
        for (int i = 0; i < ids.Count; i++)
        {
            string? id = ((string)ids[i]);
            IDictionary<string, object> asset = this.safeDict(assets, id, new Dictionary<string, object>() {});
            IDictionary<string, object> assetSettings = this.safeDict(settingsById, id, new Dictionary<string, object>() {});
            // an operation that is not listed for an asset is not available for it
            List<object> actions = this.safeList(assetSettings, "actions", new List<object>() {});
            Dictionary<string, object> currency = this.parseCurrency(this.extend(asset, new Dictionary<string, object>() {
                { "actions", actions },
            }));
            string? code = ((string)(currency.ContainsKey("code") ? currency["code"] : null));
            result[(string)code] = currency;
        }
        return ((IDictionary<string, object>)((object)(result)));
    }

    public override Dictionary<string, object> parseCurrency(object rawCurrency)
    {
        string? id = this.safeString(rawCurrency, "symbol");
        string? code = this.safeCurrencyCode(id);
        string? assetType = this.safeString(rawCurrency, "assetType");
        bool? enabled = this.safeBool(rawCurrency, "enabled", false);
        string? removedAt = this.safeString(rawCurrency, "removedAt");
        bool active = (enabled == true) && ((removedAt == null));
        List<object> actions = this.safeList(rawCurrency, "actions", new List<object>() {});
        bool deposit = this.inArray("deposit", actions);
        bool withdraw = this.inArray("withdrawal", actions);
        // the exponent is only published for a handful of assets, fall back to the usual decimals
        string defaultExponent = (assetType == "fiat") ? "2" : "8";
        double? precision = this.parseNumber(this.parsePrecision(this.safeString(rawCurrency, "exponent", defaultExponent)));
        Dictionary<string, object> networks = new Dictionary<string, object>() {};
        string? networkId = this.safeString(rawCurrency, "network");
        string? networkCode = this.networkIdToCode(networkId, code);
        if ((networkCode != null))
        {
            networks[(string)networkCode] = new Dictionary<string, object>() {
                { "info", rawCurrency },
                { "id", networkId },
                { "network", networkCode },
                { "active", active },
                { "deposit", deposit },
                { "withdraw", withdraw },
                { "fee", null },
                { "precision", precision },
                { "limits", new Dictionary<string, object>() {
                    { "withdraw", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "deposit", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                } },
            };
        }
        return this.safeCurrencyStructure(new Dictionary<string, object>() {
            { "info", rawCurrency },
            { "id", id },
            { "code", code },
            { "name", this.safeString(rawCurrency, "name") },
            { "active", active },
            { "deposit", deposit },
            { "withdraw", withdraw },
            { "networks", networks },
            { "fee", null },
            { "precision", precision },
            { "type", (assetType == "fiat") ? "fiat" : "crypto" },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "deposit", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "withdraw", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
        });
    }

