        //
        return this.parseOrder(response, market);
    }

    /**
     * @ignore
     * @method
     * @name bit2me#createOrderRequest
     * @description helper function to build the request body for createOrder
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base currency
     * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the request body
     */
    public virtual Dictionary<string, object> createOrderRequest(object symbol, object type, object side, object amount, object price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> market = this.market(symbol);
        bool isMarketOrder = ((type is "market"));
        string? stopLossPrice = this.safeString(parameters, "stopLossPrice");
        string? takeProfitPrice = this.safeString(parameters, "takeProfitPrice");
        string? stopLimitPrice = this.safeString(parameters, "stopLimitPrice");
        bool isOco = ((stopLossPrice != null)) && ((takeProfitPrice != null));
        // a lone stop loss or take profit is a stop-limit order, the exchange triggers it in either direction
        string? triggerPrice = this.safeStringN(parameters, new List<object>() {"triggerPrice", "stopPrice", "stopLossPrice", "takeProfitPrice"});
        string? cost = this.safeString(parameters, "cost");
        // every order placed through the library is tagged with the broker id, CCXT-<id>
        string? clientOrderId = this.safeString(parameters, "clientOrderId");
        if ((clientOrderId == null))
        {
            string brokerId = this.safeString(this.options, "brokerId", "CCXT");
            string prefix = (brokerId + "-");
            clientOrderId = (prefix + this.uuid());
        }
        object query = this.omit(parameters, new List<object>() {"triggerPrice", "stopPrice", "stopLossPrice", "takeProfitPrice", "stopLimitPrice", "cost", "clientOrderId"});
        bool? postOnly = false;
        IList<object> postOnlyqueryVariable = (IList<object>)this.handlePostOnly(isMarketOrder, false, query);
        postOnly = (bool?)postOnlyqueryVariable[0];
        query = postOnlyqueryVariable[1];
        string? timeInForce = this.safeStringUpper(query, "timeInForce");
        query = this.omit(query, "timeInForce");
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
            { "side", side },
            { "orderType", type },
        };
        if (isOco)
        {
            if (!(side is "sell"))
            {
                throw new InvalidOrder ((this.id + " createOrder() only supports OCO orders on the sell side")) ;
            }
            if (isMarketOrder)
            {
                throw new InvalidOrder ((this.id + " createOrder() OCO legs are limit orders, use the limit type")) ;
            }
            request["orderType"] = "oco";
            request["amount"] = this.amountToPrecision(symbol, amount);
            request["takeProfitPrice"] = this.priceToPrecision(symbol, takeProfitPrice);
            request["stopPrice"] = this.priceToPrecision(symbol, stopLossPrice);
            string? stopLossLimit = stopLimitPrice;
            if ((stopLossLimit == null))
            {
                stopLossLimit = ((price != null)) ? this.numberToString(price) : stopLossPrice;
            }
            request["stopLimitPrice"] = this.priceToPrecision(symbol, stopLossLimit);
        } else if (isMarketOrder)
        {
            if ((triggerPrice != null))
            {
                throw new InvalidOrder ((this.id + " createOrder() does not support stop-market orders, use a limit price to place a stop-limit order")) ;
            }
            string? quoteAmount = null;
            if ((cost != null))
            {
                quoteAmount = cost;
            } else if (((side is "buy")) && ((price != null)))
            {
                // the unified convention for market buy orders, the cost to spend is amount * price
                quoteAmount = Precise.stringMul(this.numberToString(amount), this.numberToString(price));
            }
            if ((quoteAmount != null))
            {
                request["amount"] = this.costToPrecision(symbol, quoteAmount);
                request["amountInQuote"] = true;
            } else
            {
                request["amount"] = this.amountToPrecision(symbol, amount);
            }
        } else
        {
            if ((price == null))
            {
                throw new ArgumentsRequired ((((this.id + " createOrder() requires a price argument for a ") + (type)) + " order")) ;
            }
            request["amount"] = this.amountToPrecision(symbol, amount);
            request["price"] = this.priceToPrecision(symbol, price);
            if ((triggerPrice != null))
            {
                request["orderType"] = "stop-limit";
                request["stopPrice"] = this.priceToPrecision(symbol, triggerPrice);
            }
        }
        if ((postOnly == true))
        {
            request["postOnly"] = true;
        }
        if ((timeInForce != null))
        {
            request["timeInForce"] = timeInForce;
        }
        if (!isOco)
        {
            // the exchange does not accept a clientOrderId on oco orders
            request["clientOrderId"] = clientOrderId;
        }
        return this.extend(request, query);
    }

