            }
            IDictionary<string, object> first = this.safeDict(orders, 0, new Dictionary<string, object>() {});
            return this.parseOrder(first, market);
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", id },
        };
        Dictionary<string, object> response = await this.privateGetV1TradingOrderId(this.extend(request, parameters));
        //
        //     {
        //         "cancelReason": null,
        //         "clientOrderId": null,
        //         "cost": 15600.12,
        //         "createdAt": "2024-05-07T14:08:30.961Z",
