        //         "orderAmount": 0.35,
        //         "orderGroupId": null,
        //         "orderType": "limit",
        //         "postOnly": null,
        //         "price": 65000.5,
        //         "side": "buy",
        //         "status": "open",
        //         "stopPrice": 0,
        //         "symbol": "BTC/EUR",
        //         "timeInForce": "GTC",
        //         "updatedAt": "2024-05-07T14:09:02.310Z",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
