    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "open", "open" },
            { "inactive", "open" },
            { "filled", "closed" },
            { "cancelled", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

    public virtual string? parseOrderType(object type)
    {
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "limit", "limit" },
            { "market", "market" },
            { "stop-limit", "limit" },
        };
        return this.safeString(types, type, type);
    }

    public override ccxt.Order parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // createOrder, cancelOrder, fetchOrder, fetchOrders
        //
        //     {
        //         "cancelReason": null,
        //         "clientOrderId": null,
        //         "cost": 15600.12,
        //         "createdAt": "2024-05-07T14:08:30.961Z",
        //         "feeAmount": 15.60012,
        //         "feeCurrency": "EUR",
        //         "filledAmount": 0.24,
        //         "id": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //         "orderAmount": 0.35,
        //         "orderGroupId": null,
        //         "orderType": "limit",
        //         "postOnly": null,
        //         "price": 65000.5,
        //         "side": "buy",
        //         "status": "open",
        //         "stopPrice": 0,
        //         "symbol": "BTC/EUR",
        //         "timeInForce": "GTC",
        //         "updatedAt": "2024-05-07T14:09:02.310Z",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        string? marketId = this.safeString(order, "symbol");
        Dictionary<string, object> resolvedMarket = this.safeMarket(marketId, market);
        Int64? timestamp = this.parse8601(this.safeString(order, "createdAt"));
        string? rawType = this.safeString(order, "orderType");
        Dictionary<string, object> fee = null;
        double? feeCost = this.safeNumber(order, "feeAmount");
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", this.safeCurrencyCode(this.safeString(order, "feeCurrency")) },
            };
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", this.safeString(order, "id") },
            { "clientOrderId", this.safeString(order, "clientOrderId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", this.parse8601(this.safeString(order, "updatedAt")) },
            { "symbol", (resolvedMarket != null && resolvedMarket.ContainsKey("symbol") ? resolvedMarket["symbol"] : null) },
            { "type", this.parseOrderType(rawType) },
            { "timeInForce", this.safeString(order, "timeInForce") },
            { "postOnly", this.safeBool(order, "postOnly") },
            { "reduceOnly", null },
            { "side", this.safeStringLower(order, "side") },
            { "price", this.omitZero(this.safeString(order, "price")) },
            { "triggerPrice", this.omitZero(this.safeString(order, "stopPrice")) },
            { "amount", this.safeString(order, "orderAmount") },
            { "cost", this.safeString(order, "cost") },
            { "average", null },
            { "filled", this.safeString(order, "filledAmount") },
            { "remaining", null },
            { "status", this.parseOrderStatus(this.safeString(order, "status")) },
            { "fee", fee },
            { "trades", null },
        }, resolvedMarket);
    }

