    /**
     * @method
     * @name bit2me#transfer
     * @description transfer currency internally between the bit2me wallet and the trading (pro) wallet
     * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/deposit/post
     * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/withdraw/post
     * @param {string} code unified currency code
     * @param {float} amount amount to transfer
     * @param {string} fromAccount 'funding' (the bit2me wallet) or 'spot' (the trading wallet)
     * @param {string} toAccount 'funding' (the bit2me wallet) or 'spot' (the trading wallet)
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transfer structure](https://docs.ccxt.com/#/?id=transfer-structure)
     */
    public async override Task<ccxt.TransferEntry> Transfer(string code, double amount, string fromAccount, string toAccount, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> currency = this.currency(code);
        IDictionary<string, object> accountsByType = this.safeDict(this.options, "accountsByType", new Dictionary<string, object>() {});
        string? fromId = this.safeString(accountsByType, fromAccount, fromAccount);
        string? toId = this.safeString(accountsByType, toAccount, toAccount);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "currency", (currency.ContainsKey("id") ? currency["id"] : null) },
            { "amount", this.currencyToPrecision(code, amount) },
        };
        Dictionary<string, object> response = null;
        if ((fromId == "wallet") && (toId == "trading"))
        {
            response = await this.privatePostV1TradingWalletDeposit(this.extend(request, parameters));
        } else if ((fromId == "trading") && (toId == "wallet"))
        {
            response = await this.privatePostV1TradingWalletWithdraw(this.extend(request, parameters));
        } else
        {
            throw new BadRequest ((this.id + " transfer() only supports transfers between the funding account (bit2me wallet) and the spot account (trading wallet)")) ;
        }
        //
        //     {
        //         "balance": 1350.5,
        //         "blockedBalance": 0,
        //         "createdAt": "2023-09-13T14:05:42.149Z",
        //         "currency": "EUR",
        //         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //         "rawBalance": "1350.5",
        //         "rawBlockedBalance": "0",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        Dictionary<string, object> transfer = this.parseTransfer(response, currency);
        transfer["amount"] = amount;
        transfer["fromAccount"] = fromAccount;
        transfer["toAccount"] = toAccount;
        return ccxt.BaseExchange.ToTransferEntry(transfer);
    }

    /**
     * @method
     * @name bit2me#fetchTransfers
     * @description fetch the history of movements between the bit2me wallet and the trading (pro) wallet
     * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/movement/get
     * @param {string} [code] unified currency code of the currency transferred
     * @param {int} [since] the earliest time in ms to fetch transfers for
     * @param {int} [limit] the maximum number of transfer structures to retrieve, default 100, max 100
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] the latest time in ms to fetch transfers for
     * @param {string} [params.movementType] 'deposit' or 'withdrawal', to fetch only one direction
     * @returns {object[]} a list of [transfer structures](https://docs.ccxt.com/#/?id=transfer-structure)
     */
    public async override Task<List<ccxt.TransferEntry>> FetchTransfers(string code = null, Int64? since = null, Int64? limit = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        IDictionary<string, object> currency = null;
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        if ((code != null))
        {
            currency = this.currency(code);
            request["currency"] = (currency.ContainsKey("id") ? currency["id"] : null);
        }
        if ((since != null))
        {
            request["from"] = this.iso8601(since);
        }
        if ((limit != null))
        {
            request["limit"] = Math.Min(limit.Value, 100);
        }
        IList<object> untilqueryVariable = (IList<object>)this.handleParamInteger(parameters, "until");
        Int64? until = (Int64?)untilqueryVariable[0];
        IDictionary<string, object> query = ((IDictionary<string, object>)untilqueryVariable[1]);
        if (!(until == null))
        {
            request["to"] = this.iso8601(until);
        }
        List<object> response = await this.privateGetV1TradingMovement(this.extend(request, query));
        //
        //     [
        //         {
        //             "amount": 100,
        //             "createdAt": "2025-03-10T09:30:00.000Z",
        //             "currency": "EUR",
        //             "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        //             "movementType": "deposit",
        //             "serviceOrderName": "wallet",
        //             "status": "completed",
        //             "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        //         }
        //     ]
        //
        return ccxt.BaseExchange.ToTransferEntryList(this.parseTransfers(response, currency, since, limit));
    }

    public override Dictionary<string, object> parseTransfer(object transfer, IDictionary<string, object> currency = null)
    {
        //
        // transfer
        //
        //     {
        //         "balance": 1350.5,
        //         "blockedBalance": 0,
        //         "createdAt": "2023-09-13T14:05:42.149Z",
        //         "currency": "EUR",
        //         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //         "rawBalance": "1350.5",
        //         "rawBlockedBalance": "0",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        // fetchTransfers
        //
        //     {
        //         "amount": 100,
        //         "createdAt": "2025-03-10T09:30:00.000Z",
        //         "currency": "EUR",
        //         "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        //         "movementType": "deposit",
        //         "serviceOrderName": "wallet",
        //         "status": "completed",
        //         "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        //     }
        //
        string? currencyId = this.safeString(transfer, "currency");
        string? movementType = this.safeString(transfer, "movementType");
        IDictionary<string, object> accountsById = this.safeDict(this.options, "accountsById", new Dictionary<string, object>() {});
        string? fromAccount = null;
        string? toAccount = null;
        string? id = null;
        Int64? timestamp = null;
        string? status = null;
        if ((movementType != null))
        {
            // a movement from the historical list
            id = this.safeString(transfer, "id");
            timestamp = this.parse8601(this.safeString(transfer, "createdAt"));
            status = this.parseTransferStatus(this.safeString(transfer, "status"));
            string? wallet = this.safeString(accountsById, "wallet");
            string? trading = this.safeString(accountsById, "trading");
            fromAccount = (movementType == "deposit") ? wallet : trading;
            toAccount = (movementType == "deposit") ? trading : wallet;
        } else
        {
            // the trading wallet returned by deposit/withdraw, createdAt is the wallet creation date
            status = "ok";
        }
        return new Dictionary<string, object>() {
            { "info", transfer },
            { "id", id },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "currency", this.safeCurrencyCode(currencyId, currency) },
            { "amount", this.safeNumber(transfer, "amount") },
            { "fromAccount", fromAccount },
            { "toAccount", toAccount },
            { "status", status },
        };
    }

    public virtual string? parseTransferStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "completed", "ok" },
            { "pending", "pending" },
            { "failed", "failed" },
            { "cancelled", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Int64 nonce()
    {
        // the nonce must be a unix timestamp in milliseconds, within 5 seconds of the server clock
        return this.milliseconds();
    }

    public override Dictionary<string, object> sign(string path, IList<object> api = null, string method = null, object parameters = null)
    {
        api ??= new List<object>();
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        string? apiName = ((string)(api != null && 0 < api.Count ? api[0] : null));
        Dictionary<string, object> requestHeaders = null;
        string? requestBody = null;
        object query = this.omit(parameters, this.extractParams(path));
        string url = ("/" + this.implodeParams(path, parameters));
        bool isGetOrDelete = ((method == "GET")) || ((method == "DELETE"));
        if (isGetOrDelete)
        {
            if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
            {
                url = url + ("?" + this.urlencode(query));
            }
        }
        if (apiName == "private")
        {
            this.checkRequiredCredentials();
            // https://api.bit2me.com/docs/guides/authentication
            // message = nonce:path[:compactJsonBody] -> sha256 (binary) -> hmac-sha512 (base64)
            string nonce = this.nonce().ToString();
            string message = ((nonce + ":") + url);
            if (!isGetOrDelete)
            {
                // always send a json body, some http clients label an empty body as octet-stream and the gateway rejects it
                // an empty query is spelled out, php encodes an empty array as [] and would sign and post that instead of {}
                if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
                {
                    requestBody = this.json(query);
                } else
                {
                    requestBody = "{}";
                }
                message = message + (":" + requestBody);
            }
            byte[] digest = ((byte[])this.hash(this.encode(message), sha256, "binary"));
            string signature = this.hmac(digest, this.encode(this.secret), sha512, "base64");
            requestHeaders = new Dictionary<string, object>() {
                { "x-api-key", this.apiKey },
                { "x-nonce", nonce },
                { "api-signature", signature },
            };
            if ((requestBody != null))
            {
                requestHeaders["Content-Type"] = "application/json";
            }
        }
        string? apiUrl = this.safeString((this.urls != null && this.urls.ContainsKey("api") ? this.urls["api"] : null), apiName);
        if ((apiUrl == null))
        {
            throw new NotSupported ((((this.id + " does not have a URL for ") + apiName) + " endpoints")) ;
        }
        string fullUrl = (apiUrl + url);
        return new Dictionary<string, object>() {
            { "url", fullUrl },
            { "method", method },
            { "body", requestBody },
            { "headers", requestHeaders },
        };
    }

    public override object handleErrors(Int64? httpCode, string reason, string url, string method, object headers, object body, object response, Dictionary<string, object> requestHeaders, object requestBody)
    {
        if ((response == null))
        {
            return null;  // fallback to default error handler
        }
        //
        //     {"statusCode":404,"error":"Not Found","message":"Market not found for symbol FOO/BAR","reqId":"9834b8a8-97b8-470d-ade2-3d31687c0723"}
        //     {"code":403,"description":"invalid credentials"}
        //     {"message":"Validation errors","errors":[{"code":"INVALID_REQUEST_PARAMETER","message":"Invalid parameter (symbol): Value is required but was not provided","in":"query","name":"symbol"}]}
        //     {"message":["type must be one of the following values: all, fiat, crypto"],"error":"Bad Request","statusCode":400}
        //     {"statusCode":412,"error":"Precondition Failed","message":"...","errorPayload":{"code":"ORDER_AMOUNT_LOWER_MARKET_MIN"}}
        //
        string? errorCode = this.safeString2(response, "code", "statusCode");
        List<object> errorsList = this.safeList(response, "errors");
        IDictionary<string, object> errorPayload = this.safeDict(response, "errorPayload", new Dictionary<string, object>() {});
        string? payloadCode = this.safeString(errorPayload, "code");
        if (((errorCode != null)) || ((errorsList != null)) || ((payloadCode != null)))
        {
            string? message = this.safeStringN(response, new List<object>() {"message", "description", "error"});
            string feedback = ((this.id + " ") + (body));
            this.throwExactlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("exact") ? this.exceptions["exact"] : null), payloadCode, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("broad") ? this.exceptions["broad"] : null), message, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("broad") ? this.exceptions["broad"] : null), body, feedback);
            this.throwExactlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("exact") ? this.exceptions["exact"] : null), errorCode, feedback);
            throw new ExchangeError (feedback) ;
        }
        return null;
    }
